UPDATE coupons
SET status = #{status}
WHERE id = #{couponId}

mapper.insert:
INSERT INTO member_coupons (coupon_id, member_id)
SELECT #{couponId}, m.id
FROM members m
WHERE m.id = #{memberId}
  AND m.status = 'ACTIVE'
  AND m.role = 'USER'
  AND NOT EXISTS (
      SELECT 1
      FROM member_coupons mc
      WHERE mc.coupon_id = #{couponId}
        AND mc.member_id = #{memberId}
  )

